// ⓪ ENTRADA · LLAVE · CC#2 · 2026-10-09 · flujo `zero-risk/oficina-turno` (UN paso de la oficina por ejecución). INACTIVO.
// Lo despierta la puerta (o el vigía, o este mismo flujo para el paso siguiente) con { encargo_id, turno } y la llave de despacho. Nada de aquí paga: solo valida.
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' && !Array.isArray(w.body) ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}

const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) throw new Error('OFICINA_TURNO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) · el flujo queda cerrado · E67.')
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) throw new Error('OFICINA_TURNO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · E67.')

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(body.encargo_id || ''))) throw new Error('OFICINA_TURNO_SIN_ENCARGO · encargo_id no es un uuid · se DETIENE')
const t = body.turno && typeof body.turno === 'object' ? body.turno : null
if (!t || !Number.isInteger(t.n) || t.n < 1) throw new Error('OFICINA_TURNO_SIN_NUMERO · falta turno.n (entero ≥ 1) · se DETIENE')
if (t.tipo !== 'agente' && t.tipo !== 'portero') throw new Error('OFICINA_TURNO_TIPO_INVALIDO · este flujo solo ejecuta pasos de agente o de portero (llegó ' + JSON.stringify(t.tipo) + ')')
if (!t.pedido || typeof t.pedido !== 'object') throw new Error('OFICINA_TURNO_SIN_PEDIDO · falta turno.pedido · se DETIENE')
if (t.tipo === 'agente' && (typeof t.pedido.agent_name !== 'string' || typeof t.pedido.task !== 'string' || !t.pedido.task)) throw new Error('OFICINA_TURNO_PEDIDO_INVALIDO · el pedido de un agente necesita agent_name y task')

return [{ json: { encargo_id: String(body.encargo_id), turno: t, dry_run: t.pedido.dry_run === true } }]

// ① EL PORTERO · CC#2 · 2026-10-09 · convierte la respuesta del flujo `zero-risk/portero` (o el modo seco) en el cuerpo de `POST /api/oficina/turnos {accion:'resultado'}`.
// El texto del portero es OPACO para la sala (se le pasa a los agentes tal cual); un error del portero no frena la oficina por sí solo: se manda como error y la sala decide (cierra fallido: sin material no se sigue a ciegas).
// 🔴 El contrato de la respuesta del portero NO está verificado campo a campo: se manda la respuesta entera como texto.
const e = $('⓪ Entrada · llave').first().json
const r = $input.first().json || {}
if (e.dry_run === true) {
  return [{ json: { ...e, resultado_body: { accion: 'resultado', encargo_id: e.encargo_id, n: e.turno.n, texto: '(simulado) material del portero: sin llamada al portero en modo seco', costo_usd: 0, workflow_execution_id: $execution.id } } }]
}
const b = r.body && typeof r.body === 'object' ? r.body : r
const body = { accion: 'resultado', encargo_id: e.encargo_id, n: e.turno.n, workflow_execution_id: $execution.id, costo_usd: typeof b.costo_usd === 'number' ? b.costo_usd : (typeof b.cost_usd === 'number' ? b.cost_usd : 0) }
if (b.error && typeof b.error === 'object') body.error = 'el portero no respondió · ' + String(b.error.message || 'sin detalle').slice(0, 200)
else if (b.rechazo) body.error = 'el portero rechazó el pedido · ' + JSON.stringify(b.rechazo).slice(0, 240)
else if (Object.keys(b).length === 0) body.error = 'el portero contestó vacío'
else body.texto = JSON.stringify(b).slice(0, 20000)
return [{ json: { ...e, resultado_body: body } }]

// ② ARMAR EL PEDIDO · CC#2 · 2026-10-09 · el cuerpo que se manda a /api/agents/run-sdk (el agente solo se invoca desde un flujo con workflow_id) o, en modo seco, la respuesta SIMULADA.
// 🔴 En modo seco NO se llama a ningún proveedor ni al corredor: la respuesta sale de un molde válido por esquema (el «modelo simulado»), igual que `simulacro_respuesta` de la pieza.
// 🔴 `force_restart: true` y `dispatch_key` propios del paso: una respuesta vieja guardada no se reutiliza (lección del flujo de prueba).
const e = $input.first().json
const t = e.turno
const p = t.pedido

// ── moldes del modelo simulado (válidos contra los esquemas de la oficina)
const indices = (task) => [...String(task).matchAll(/índice (\d+)/g)].map((m) => Number(m[1]))
// ── r78 · los refs del pedido: elementos del kit («- e01: …»), roles de lámina del carrusel («Roles de lámina posibles …: hook, problem, …») o las imágenes a generar («## Imágenes que hay que GENERAR … - ref: …»)
const refsDeKit = (task) => [...String(task).matchAll(/^- (e\d+):/gm)].map((m) => m[1])
const refsDe = (task) => { const kit = refsDeKit(task); if (kit.length) return kit; const m = /Roles de lámina posibles[^:\n]*:\s*([^\n]+)/.exec(String(task)); return m ? m[1].split(',').map((x) => x.trim()).filter(Boolean) : [] }
const refsAGenerar = (task) => { const i = String(task).search(/## Imágenes que hay que GENERAR/); if (i < 0) return []; const sec = String(task).slice(i).split(/\n## /)[0]; return [...sec.matchAll(/^- ([^:\n]+):/gm)].map((m) => m[1].trim()) }
const SIMULADOS = {
  'visual_direction.v1': () => ({ resumen: '(simulado) dirección visual', decision: { modo: 'generada', motivo: '(simulado)' }, reglas_de_imagen: { obligatorio: [], prohibido: [] } }),
  'prompts.v1': () => ({ prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] }),
  'observacion_imagen.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'pieza_post.v1': () => ({ pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'fichas.v1': () => ({ fichas: [] }),
  'resolucion.v1': () => ({ respuestas: [] }),
  // ── r78 · salas 2 y 3 (los refs salen del propio pedido)
  'direccion_imagenes.v1': (task) => { const refs = refsDe(task); return { resumen: '(simulado) dirección visual', estilo: '(simulado)', imagenes: refs.length ? [{ ref: refs[0], modo: 'generada', motivo: '(simulado)' }] : [], reglas_de_imagen: { obligatorio: [], prohibido: [] } } },
  'prompts_por_ref.v1': (task) => ({ imagenes: refsAGenerar(task).map((ref) => ({ ref, prompts: [{ prompt: '(simulado) un plato visto desde arriba con luz natural lateral, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) cenital' }, { prompt: '(simulado) el mismo plato a nivel de mesa con fondo desenfocado, sin personas, sin texto, sin logotipos', idea_en_una_linea: '(simulado) nivel de mesa' }] })) }),
  'observacion_imagenes.v1': (task) => { const ix = indices(task); return { imagenes: ix.map((indice) => ({ indice, reglas: [], texto_en_imagen: [], marcas: [], personas: 0 })), preferencia: ix } },
  'copy_base.v1': () => ({ texto_base: 'Primera línea simulada\nSegunda línea simulada\nTercera línea simulada\nCuarta línea simulada\nEscríbenos', pie_de_foto: '(simulado) pie de foto de prueba', hashtags: [] }),
  'laminas.v1': () => ({ laminas: [{ rol: 'hook', headline: 'Primera línea simulada' }, { rol: 'problem', headline: 'Segunda línea simulada' }, { rol: 'reframe', headline: 'Tercera línea simulada' }, { rol: 'benefit', headline: 'Cuarta línea simulada' }, { rol: 'cta', headline: 'Escríbenos', cta: 'Escríbenos' }] }),
  'estructura.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, rol: '(simulado) rol', beat: '(simulado) beat', mood: '(simulado) mood' })) }),
  'copy_kit.v1': (task) => ({ elementos: refsDeKit(task).map((ref) => ({ ref, headline: '(simulado) titular' })) }),
  'resolucion_solo.v1': () => ({ respuestas: [] }),
  'resolucion_copy_base.v1': () => ({ respuestas: [] }),
  'resolucion_copy_kit.v1': () => ({ respuestas: [] }),
  'resolucion_estructura.v1': () => ({ respuestas: [] }),
  'resolucion_laminas.v1': () => ({ respuestas: [] }),
}

if (e.dry_run === true) {
  const molde = SIMULADOS[p.esquema]
  // r78 · un esquema sin molde NO mata la ejecución (el encargo se quedaba «corriendo» en silencio): el motor recibe el error y el encargo falla visible
  if (!molde) return [{ json: { ...e, simulado: true, resultado_body: { accion: 'resultado', encargo_id: e.encargo_id, n: t.n, error: 'OFICINA_SIN_MOLDE_SIMULADO · no hay respuesta simulada para el esquema ' + JSON.stringify(p.esquema), costo_usd: 0, workflow_execution_id: $execution.id } } }]
  return [{ json: { ...e, simulado: true, resultado_body: { accion: 'resultado', encargo_id: e.encargo_id, n: t.n, texto: JSON.stringify(molde(p.task)), costo_usd: 0, workflow_execution_id: $execution.id } } }]
}

const cuerpo = {
  agent: p.agent_name,
  task: p.task,
  client_id: p.client_id,
  workflow_id: $workflow.id,
  workflow_execution_id: $execution.id,
  callback_url: $execution.resumeUrl,
  // ronda 69 · la vuelta la entrega el corredor cuando el agente puede (diseño de láminas); si no puede, run-sdk lo ignora y la vuelta sigue por Vercel con la recuperación del resultado
  callback_mode: 'runner',
  force_restart: true,
  dry_run: false,
  max_budget_usd: p.max_budget_usd,
  thinking_mode: p.thinking_mode || 'disabled',
  extra: { ...(p.extra || {}), dispatch_key: t.dispatch_key },
  ...(Array.isArray(p.images) && p.images.length ? { images: p.images, images_mode: 'base64' } : {}),
}
return [{ json: { ...e, simulado: false, cuerpo } }]

// ② ¿ACEPTÓ EL PEDIDO? · CC#2 · 2026-10-09 · mismo criterio que la pieza: run-sdk contesta SÍNCRONO 202 `{accepted:true}` si acepta (la vuelta llega después por el callback) o un RECHAZO con `error`.
// Un rechazo síncrono significa que el agente NO arrancó: se avisa YA a la oficina (resultado con error) en lugar de esperar la espera entera.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const r = e.body && typeof e.body === 'object' ? e.body : e
// el nodo HTTP falló (red, tiempo): n8n entrega `{error:{message…}}` con `error` OBJETO · el rechazo de run-sdk trae `error` como TEXTO
if (r.error && typeof r.error === 'object') {
  return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', encargo_id: c.encargo_id, n: c.turno.n, error: 'OFICINA_PEDIDO_NO_LLEGO · ' + String(r.error.message || r.error.name || 'sin detalle').slice(0, 200), costo_usd: 0, workflow_execution_id: $execution.id } } }]
}
if (r.accepted === true) return [{ json: { ...c, aceptado: true } }]
const partes = [r.error, r.code, r.detail].filter((x) => x !== undefined && x !== null && x !== '')
return [{ json: { ...c, aceptado: false, resultado_body: { accion: 'resultado', encargo_id: c.encargo_id, n: c.turno.n, error: 'OFICINA_PEDIDO_RECHAZADO · ' + (partes.length ? partes.map(String).join(' · ').slice(0, 240) : JSON.stringify(r).slice(0, 200)), costo_usd: 0, workflow_execution_id: $execution.id } } }]

// ② LA VUELTA DEL AGENTE (o el portero) · CC#2 · 2026-10-09 · convierte lo que volvió en el cuerpo de `POST /api/oficina/turnos {accion:'resultado'}`.
// Un fallo declarado del agente (`success:false`: corte por tope, etc.) NO es una vuelta: su texto, si trae, es PARCIAL y no se manda como respuesta (se manda el error).
// El costo es el que reporta el corredor (el libro de la sala lo suma); sin costo reportado se manda 0 y la sala lo declara.
const c = $('② Armar el pedido').first().json
const e = $input.first().json || {}
const cuerpo = e.body ? e.body : e
const fallo = cuerpo.success === false ? String(cuerpo.error || cuerpo.error_kind || 'sin detalle') : null
const texto = fallo ? '' : String(cuerpo.response || cuerpo.result || cuerpo.output || cuerpo.text || '')
const costo = typeof cuerpo.cost_usd === 'number' ? cuerpo.cost_usd : (typeof cuerpo.costUsd === 'number' ? cuerpo.costUsd : 0)
const body = { accion: 'resultado', encargo_id: c.encargo_id, n: c.turno.n, costo_usd: costo, workflow_execution_id: $execution.id }
if (fallo) body.error = 'el agente FALLÓ · ' + fallo + (cuerpo.partial === true ? ' · (había texto parcial: no se usa)' : '')
else if (texto.trim() === '') body.error = 'la vuelta del agente llegó vacía (o se agotó la espera)'
else body.texto = texto
if (typeof cuerpo.tokens_in === 'number') body.tokens_in = cuerpo.tokens_in
if (typeof cuerpo.tokens_out === 'number') body.tokens_out = cuerpo.tokens_out
return [{ json: { ...c, resultado_body: body } }]

// ③ ¿Y AHORA? · CC#2 · 2026-10-09 · decide qué sigue con la respuesta REAL de `POST /api/oficina/turnos` (statusCode + body).
//   200 `esperar` → el SIGUIENTE paso: se vuelve a despertar este mismo flujo (una ejecución por paso: ninguna pasa de unos minutos)
//   200 `cerrado` → el encargo terminó (bandeja, desacuerdo, tope o fallido): se manda el CABLE a la sala con el resultado REAL
//   cualquier otra respuesta (409 turno no esperado, 5xx…) → se DETIENE con su motivo (nunca se da por bien)
const c = $('⓪ Entrada · llave').first().json
const e = $input.first().json || {}
if (e.error && typeof e.error === 'object') throw new Error('OFICINA_RESULTADO_NO_LLEGO · POST /api/oficina/turnos falló antes de recibir respuesta (' + String(e.error.message || e.error.name || 'sin detalle').slice(0, 160) + ')')
const status = Number(e.statusCode)
const b = e.body && typeof e.body === 'object' ? e.body : {}
if (status === 200 && b.accion === 'esperar' && b.turno) return [{ json: { ruta: 'esperar', turno_body: { encargo_id: c.encargo_id, turno: b.turno } } }]
if (status === 200 && b.accion === 'cerrado') {
  const ref = b.sala_ref && typeof b.sala_ref === 'object' ? b.sala_ref : {}
  return [{ json: { ruta: 'cable', payload_cable: {
    event_type: 'run_completed', worker_id: $workflow.id, worker_name: 'oficina',
    resultado: String(b.resultado_para_la_sala || 'fallido'), encargo_id: c.encargo_id, estado: b.estado || null, con_desacuerdo: b.con_desacuerdo === true, simulado: b.simulado === true,
    _sala_correlation_id: ref._sala_correlation_id || null, _journey_id: ref._journey_id || null, ts: new Date().toISOString(),
  } } }]
}
throw new Error('OFICINA_TURNO_RECHAZADO · /api/oficina/turnos contestó ' + status + ' · ' + String(b.error || b.detalle || JSON.stringify(b)).slice(0, 240) + ' · se DETIENE')
